require "bigdecimal"
require "date"

module DfeRb
  module Nfe
    # Official tables shipped with the gem (data/, regenerated by script/update_tables):
    # the IBS/CBS tax classifications (cClassTrib) and presumed credits (cCredPres) of IT
    # 2025.002, the CFOP
    # table (IT 2023.002), the TIPI's IPI rates (Decreto 11.158/2022 and its updates), the
    # CESTs (Conv. ICMS 142/2018) and the payment methods and card brands (tPag of IT 2024.002,
    # tBand). Loaded on first use.
    module Tables
      DATA = File.expand_path("data", __dir__)
      # The shipped IT 2025.002 tables are v1.71's, in production since this day. The tables
      # keep each code's current indicators only (models, presumed credit, the credit's tax
      # groups), so the rules that consult them hold for notes issued from then on; an older
      # note may carry a code an earlier version allowed.
      IBS_CBS_INDICATORS_SINCE = "2026-10-30"

      # One cClassTrib row: its CST, the rate reductions in percent, the CST's indicators,
      # whether it calls for the regular taxation group (ind_gTribRegular), whether it allows
      # the operation's presumed credit (ind_gCredPresOper), the note models it may go on
      # (indNFe, indNFCe) and the days it is in force. A revoked code stays, with its last day.
      Classification = Struct.new(:code, :cst, :ibs_reduction, :cbs_reduction, :taxed, :rate_reduction, :monophase,
        :deferral, :regular_taxation, :valid_from, :valid_until, :presumed_credit, :nfe, :nfce) do
        def taxed? = taxed
        def rate_reduction? = rate_reduction
        def monophase? = monophase
        def deferral? = deferral
        def regular_taxation? = regular_taxation
        def presumed_credit? = presumed_credit
        def nfe? = nfe
        def nfce? = nfce

        # Whether the code may go on a note of `model` ("55" or "65").
        def model?(model) = (model.to_s == "65") ? nfce : nfe

        # Whether the code is in force on `date` (a Date, a Time or "yyyy-mm-dd"). The end date
        # is taken as the first day it is no longer accepted, as the CFOP table does: the
        # codes IT 2025.002 v1.60 revoked end on 2026-01-01, having never applied in 2026.
        def valid_on?(date = Date.today)
          day = Tables.day(date)
          valid_from <= day && (valid_until.nil? || day < valid_until)
        end
      end

      # One cCredPres row (IT 2025.002 §04): whether the credit is taken on the note
      # (on_note, "Apropria via NF?") or by event, whether it's deducted from the item's tax
      # (indDeduzCredPres), whether the IBS and CBS groups are required (true), barred (false)
      # or left open (nil, where the table leaves the indicator blank) (ind_gIBSCredPres,
      # ind_gCBSCredPres), whether a payment declaration is required (indDecPag), the models it
      # may go on (indNFe, indNFCe, indCTe, indNFSe), the cClassTrib the referenced note must
      # carry (a code, or the table's words for a kind of code), and the days each tax may
      # take it (nil for none: that tax doesn't take this credit, or the table gives no day).
      PresumedCredit = Struct.new(:code, :on_note, :by_event, :deducted, :cbs, :ibs, :payment_declaration, :nfe, :nfce,
        :cte, :nfse, :referenced_classification, :cbs_from, :cbs_until, :ibs_from, :ibs_until, :description) do
        def on_note? = on_note
        def by_event? = by_event
        def deducted? = deducted
        def payment_declaration? = payment_declaration

        # Whether `tax` (:ibs or :cbs, either when nil) may take the credit on `date`, the
        # last day included. A tax without a first day never may.
        def valid_on?(date = Date.today, tax: nil)
          day = Tables.day(date)
          (tax ? [tax] : %i[ibs cbs]).any? do |name|
            from, to = (name == :ibs) ? [ibs_from, ibs_until] : [cbs_from, cbs_until]
            from && from <= day && (to.nil? || day <= to)
          end
        end
      end

      # One CFOP row: its validity and the indicators the validation rules consult (indNFe,
      # indComunica, indTransp, indDevol, indRetor, indAnula, indRemes, indComb,
      # indExcIBSCBS). `fuel` is indComb: 0, 1 (fuel group required) or 2 (carrier too).
      # Direction and scope come from the first digit: 1-3 entries, 5-7 exits; 1/5 within
      # the state, 2/6 interstate, 3/7 foreign.
      Cfop = Struct.new(:code, :valid_from, :valid_until, :nfe, :communication, :transport, :devolution, :goods_return,
        :annulment, :remittance, :fuel, :ibs_cbs_only, :title) do
        def nfe? = nfe
        def communication? = communication
        def transport? = transport
        def devolution? = devolution
        def goods_return? = goods_return
        def annulment? = annulment
        def remittance? = remittance
        def fuel? = fuel.positive?
        def ibs_cbs_only? = ibs_cbs_only
        def entry? = code.to_i < 5000
        def exit? = !entry?
        def scope = CFOP_SCOPES[code.to_i / 1000 % 4]

        # Whether the code is in force on `date` (a Date, a Time or "yyyy-mm-dd"). The end date
        # is the first day it is no longer accepted, so it is excluded (IT 2023.002).
        def valid_on?(date = Date.today)
          day = Tables.day(date)
          valid_from <= day && (valid_until.nil? || day < valid_until)
        end
      end
      CFOP_SCOPES = {1 => :internal, 2 => :interstate, 3 => :foreign}.freeze

      # One TIPI line: an 8-digit NCM, or one of its EX exceptions (EXTIPI), with the IPI
      # rate in percent. A line the table marks NT is not taxed and has no rate.
      IpiRate = Struct.new(:ncm, :ex, :rate, :non_taxed) do
        def non_taxed? = non_taxed
      end

      # One wording of a CEST of Conv. ICMS 142/2018: the NCM prefixes it is listed for (an item's
      # NCM fits when it opens with one), its description and the days it is in force, the last
      # one included (nil for no bound). The "outros" item closing a segment (01.999.00) lists no
      # NCM: it takes the segment's goods listed nowhere else, whatever their NCM.
      Cest = Struct.new(:code, :ncms, :description, :valid_from, :valid_until) do
        def catch_all? = code.end_with?("99900") && ncms.empty?
        def segment = code[0, 2]

        # Whether an NCM ("73084000" or "7308.40.00") fits it.
        def fits?(ncm)
          ncm = ncm.to_s.delete(".")
          ncms.empty? || ncms.any? { |prefix| ncm.start_with?(prefix) }
        end

        # Whether this wording is in force on `date` (a Date, a Time or "yyyy-mm-dd").
        def valid_on?(date = Date.today)
          day = Tables.day(date)
          (valid_from.nil? || valid_from <= day) && (valid_until.nil? || day <= valid_until)
        end
      end

      # One payment method (tPag): its title and the first day it is accepted, nil for the
      # codes the table started with.
      PaymentMethod = Struct.new(:code, :title, :valid_from) do
        # True for 90 (sem pagamento) and 91 (pagamento posterior), which aren't paid at issue,
        # so their vPag is 0.00 (RV YA03-30).
        def deferred? = DEFERRED_PAYMENTS.include?(code)

        # Whether the code is accepted on `date` (a Date, a Time or "yyyy-mm-dd").
        def valid_on?(date = Date.today)
          day = Tables.day(date)
          valid_from.nil? || valid_from <= day
        end
      end
      DEFERRED_PAYMENTS = %w[90 91].freeze

      module_function

      # "Campo Grande" for "5002704", or nil (DfeRb::Cities).
      def city_name(code) = Cities.name(code)

      # The IBGE code of the city called `name` in `state`, ignoring case and accents, or nil.
      def city_code(name, state) = Cities.code(name, state)

      # The Classification for a cClassTrib code, or nil. Revoked codes are kept, with the
      # day they end (Classification#valid_on?).
      def classification(code) = classifications[code.to_s]

      # Every Classification, by code, revoked ones included.
      def classification_list = classifications.values

      # The PresumedCredit for a cCredPres code ("04" or 4), or nil.
      def presumed_credit(code) = presumed_credit_index[code.to_s.rjust(2, "0")]

      def presumed_credits = presumed_credit_index.values

      # "yyyy-mm-dd" of a Date, a Time or a text that opens with one.
      def day(date) = date.respond_to?(:strftime) ? date.strftime("%F") : date.to_s[0, 10]

      # The Cfop for a code ("5102", "5.102" or 5102), or nil.
      def cfop(code) = cfop_index[code.to_s.delete(".")]

      # Every Cfop, by code. With `matching:`, those whose title has every word of it,
      # ignoring case and accents, and whose code starts with its numbers ("remessa conserto",
      # "6.9 retorno").
      def cfops(matching: nil)
        return cfop_index.values if matching.nil?

        numbers, words = fold(matching.to_s.delete(".")).split.partition { |word| word.match?(/\A\d+\z/) }
        cfop_index.values.select do |row|
          title = fold(row.title)
          numbers.all? { |number| row.code.start_with?(number) } && words.all? { |word| title.include?(word) }
        end
      end

      # The IpiRate of an NCM ("22030000" or "2203.00.00"): the line of its EX (EXTIPI, "01"
      # or "1") when one is given and the TIPI lists it, else the NCM's own. Nil when the TIPI
      # lacks the NCM.
      def ipi_rate(ncm, ex = nil)
        ncm = ncm.to_s.delete(".")
        ex = ex.to_s.strip.sub(/\A0+(?=\d)/, "")
        (ipi_index[[ncm, ex]] unless ex.empty?) || ipi_index[[ncm, nil]]
      end

      def ipi_rates = ipi_index.values

      # The Cest for a code ("0100100" or "01.001.00") in its wording of `date`, or nil when
      # it isn't in force then.
      def cest(code, on: Date.today) = cest_index[code.to_s.delete(".")]&.find { |wording| wording.valid_on?(on) }

      # The CESTs in force on `date`, by code, each in its wording of that day. With `ncm:`,
      # those it fits, the "outros" items included.
      def cests(on: Date.today, ncm: nil)
        cest_index.values.filter_map { |wordings| wordings.find { |wording| wording.valid_on?(on) } }
          .select { |cest| ncm.nil? || cest.fits?(ncm) }
      end

      # The PaymentMethod for a tPag ("17" or 17), or nil.
      def payment_method(code) = payment_index[code.to_s.rjust(2, "0")]

      def payment_methods = payment_index.values

      # Card brand names by tBand: {"01" => "Visa", ...}.
      def card_brands
        @card_brands ||= rows("card_brands.tsv").drop(1).to_h.freeze
      end

      def fold(text) = Cities.fold(text)

      def classifications
        @classifications ||= rows("classifications.tsv").drop(1).to_h do |code, cst, ibs, cbs, taxed, reduction, mono, dif, regular, from, to, credit, nfe, nfce|
          [code, Classification.new(code: code, cst: cst, ibs_reduction: BigDecimal(ibs), cbs_reduction: BigDecimal(cbs),
            taxed: taxed == "1", rate_reduction: reduction == "1", monophase: mono == "1", deferral: dif == "1",
            regular_taxation: regular == "1", valid_from: from, valid_until: to.to_s.empty? ? nil : to,
            presumed_credit: credit == "1", nfe: nfe == "1", nfce: nfce == "1").freeze]
        end.freeze
      end

      def presumed_credit_index
        @presumed_credit_index ||= rows("cred_pres.tsv").drop(1).to_h do |code, on_note, by_event, deducted, cbs, ibs, declaration, nfe, nfce, cte, nfse, reference, cbs_from, cbs_until, ibs_from, ibs_until, description|
          blank = ->(value) { value.empty? ? nil : value }
          [code, PresumedCredit.new(code: code, on_note: on_note == "1", by_event: by_event == "1", deducted: deducted == "1",
            cbs: blank.call(cbs)&.==("1"), ibs: blank.call(ibs)&.==("1"), payment_declaration: declaration == "1",
            nfe: nfe == "1", nfce: nfce == "1", cte: cte == "1", nfse: nfse == "1", referenced_classification: reference,
            cbs_from: blank.call(cbs_from), cbs_until: blank.call(cbs_until), ibs_from: blank.call(ibs_from),
            ibs_until: blank.call(ibs_until), description: description).freeze]
        end.freeze
      end

      def cfop_index
        @cfop_index ||= rows("cfop.tsv").drop(1).to_h do |code, from, to, nfe, communication, transport, devolution, goods_return, annulment, remittance, fuel, ibs_cbs_only, title|
          [code, Cfop.new(code: code, valid_from: from, valid_until: to.empty? ? nil : to, nfe: nfe == "1",
            communication: communication == "1", transport: transport == "1", devolution: devolution == "1",
            goods_return: goods_return == "1", annulment: annulment == "1", remittance: remittance == "1",
            fuel: Integer(fuel), ibs_cbs_only: ibs_cbs_only == "1", title: title).freeze]
        end.freeze
      end

      def ipi_index
        @ipi_index ||= rows("tipi.tsv").drop(1).to_h do |ncm, ex, rate|
          ex = nil if ex.empty?
          [[ncm, ex], IpiRate.new(ncm: ncm, ex: ex, rate: (BigDecimal(rate) unless rate == "NT"), non_taxed: rate == "NT").freeze]
        end.freeze
      end

      def cest_index
        @cest_index ||= rows("cests.tsv").drop(1).map do |code, from, to, ncms, description|
          Cest.new(code: code, ncms: ncms.split.freeze, description: description,
            valid_from: from.empty? ? nil : from, valid_until: to.empty? ? nil : to).freeze
        end.group_by(&:code).transform_values(&:freeze).freeze
      end

      def payment_index
        @payment_index ||= rows("payment_methods.tsv").drop(1).to_h do |code, from, title|
          [code, PaymentMethod.new(code: code, title: title, valid_from: from.empty? ? nil : from).freeze]
        end.freeze
      end

      def rows(file)
        File.readlines(File.join(DATA, file), chomp: true, encoding: "UTF-8").map { |line| line.split("\t", -1) }
      end
    end
  end
end
